     "ex": "import unittest\n\nCACHE = {}                                   # module-level state: a classic leak\n\ndef price_with_cache(sku):\n    return CACHE.setdefault(sku, 100)\n\nclass Leaky(unittest.TestCase):\n    def test_a_sets_price(self):\n        CACHE[\"MUG\"] = 999\n        self.assertEqual(price_with_cache(\"MUG\"), 999)\n    def test_b_default_price(self):\n        self.assertEqual(price_with_cache(\"MUG\"), 100)       # fails only when test_a ran first\n\nclass Isolated(Leaky):\n    def setUp(self):\n        CACHE.clear()                         # fresh state for every test\n\nfor case in (Leaky, Isolated):\n    r = unittest.TextTestRunner(verbosity=0).run(unittest.defaultTestLoader.loadTestsFromTestCase(case))\n    print(case.__name__, \"failures:\", len(r.failures))",
